# 25_compare_censored.R  Comparison of SDImax treatments with PSP thinning removals censored (replaces the benchmark parts of logs 20 and 21, which
# counted thinned stems as deaths). E4r is unaffected by the censoring (no increment interval has a removal year strictly inside), so its fits are
# taken from scripts 15 and 20; E6r is refitted by direct maximum likelihood for each treatment. No identifier printed.
suppressMessages(library(data.table)); setwd("~/jobs/koa_final_eq_20261110"); source("scripts/utils.R"); source("release/koa_step.R"); options(width = 230); POP <- 742; set.seed(20261119)
f <- readRDS("frames/frames.rds"); tr <- f$tr; cf <- koa_read_coef("release/koa_final_equations.csv"); FT <- readRDS("out/rd_final_fits.rds"); Z <- readRDS("out/sdimax_byi.rds"); RF <- Z$RF
th <- fread("~/jobs/koa_v105final_20261103/inputs/psp_origin_thinning_2026-09-16_DATA.csv"); REM <- th[removal_t1_years != "" & !is.na(removal_t1_years), .(yr = as.integer(unlist(strsplit(as.character(removal_t1_years), ";")))), by = .(Data, Install = as.character(Install))]
J <- "~/jobs/koa_brms_sdimax_20261102/out/"; sx <- fread(paste0(J, "plot_sdimax_rilong.csv")); sx[, ID := as.character(ID)]; P <- unique(tr[, .(pid, Data, Install, Plot = as.character(Plot), planted, BYI)]); P[, key := ifelse(Data == "FIA", as.character(Install), pid)]
P <- merge(P, sx[, .(key = ID, ID1 = ID)], by = "key", all.x = TRUE); k2 <- sx[, .(Data, Plot = as.character(Plot), ID2 = ID)][, if (.N == 1) .SD, by = .(Data, Plot)]; P <- merge(P, k2, by = c("Data", "Plot"), all.x = TRUE); P[, ID := ifelse(!is.na(ID1), ID1, ID2)]
P <- merge(P, sx[, .(ID, smax = SDImax_mean, lo = `SDImax_q2.5`, hi = `SDImax_q97.5`)], by = "ID", all.x = TRUE); P[, `:=`(inst = paste(Data, Install), lbyi = log(BYI), ls = log(smax), w = 1 / pmax((log(hi) - log(lo)) / 3.92, 0.05)^2)]; P <- merge(P, make_folds(P), by = "inst"); M <- P[!is.na(smax)]
s2 <- function(fm, d) lm(fm, data = d, weights = w); oof <- function(fm) { o <- rep(NA_real_, nrow(P)); for (k in sort(unique(P$fold))) o[P$fold == k] <- predict(s2(fm, M[fold != k]), P[fold == k]); setNames(exp(o), P$pid) }; full <- function(fm) setNames(exp(predict(s2(fm, M), P)), P$pid)
SMfit <- list(own = setNames(ifelse(is.na(P$smax), POP, P$smax), P$pid), one742 = setNames(rep(POP, nrow(P)), P$pid), origin = full(ls ~ planted), byi_origin = full(ls ~ lbyi + planted)); SMapp <- list(own = SMfit$own, one742 = SMfit$one742, origin = oof(ls ~ planted), byi_origin = oof(ls ~ lbyi + planted))
BG <- list(own = FT$G$b, one742 = RF$pop742$bg, origin = RF$s2_origin$bg, byi_origin = RF$s2_byi_origin$bg)
mf <- as.data.table(readRDS("frames/mf_confirmed.rds")); mf[, rid := .I]; k <- merge(mf[, .(rid, Data, Install = as.character(Install), Measure, e_Measure)], REM, by = c("Data", "Install"), allow.cartesian = TRUE)[yr > Measure & yr <= e_Measure]; mf <- mf[!(rid %in% k$rid)]; cat("mortality frame after censoring: rows", nrow(mf), "deaths", sum(mf$died), "\n")
nm <- names(FT$bm); mlfit <- function(sm) { X <- cbind(1, log(mf$dbh_m + 1), mf$dbh_m, mf$dbh_m^2, mf$BAL, log(pmax(mf$SDI_koa / sm, 0.001)), log(mf$BYI), mf$planted); mu <- c(0, colMeans(X[, -1])); sdv <- c(1, apply(X[, -1], 2, sd)); Zm <- sweep(sweep(X, 2, mu), 2, sdv, "/"); Zm[, 1] <- 1; y <- mf$died; o <- log(mf$yip)
  nll <- function(z) { h <- exp(pmin(as.numeric(Zm %*% z) + o, 30)); -sum(ifelse(y == 1, log(-expm1(-h)), -h)) }; gr <- function(z) { h <- exp(pmin(as.numeric(Zm %*% z) + o, 30)); -as.numeric(crossprod(Zm, ifelse(y == 1, h * exp(-h) / (-expm1(-h)), -h))) }
  b0 <- FT$bm; z0 <- b0 * sdv; z0[1] <- b0[1] + sum(b0[-1] * mu[-1]); op <- nlminb(z0, nll, gr, control = list(iter.max = 2000, eval.max = 4000, rel.tol = 1e-12)); b <- op$par / sdv; b[1] <- op$par[1] - sum(b[-1] * mu[-1]); list(b = setNames(b, nm), aic = 2 * op$objective + 16, gmax = max(abs(gr(op$par)))) }
BM <- lapply(SMfit, function(s) mlfit(s[mf$pid])); cat("\nE6r by treatment of SDImax (fitted with the full-data SDImax of each treatment):\n"); print(rbindlist(lapply(names(BM), function(n) cbind(SDImax = n, as.data.table(t(round(BM[[n]]$b, 4))), AIC = round(BM[[n]]$aic, 1), gmax = signif(BM[[n]]$gmax, 2)))))
xm <- function(S, BAL, BA, SDI, sm, byi, pl) cbind(1, log(S + 1), S, BAL / pmax(BA, 1e-6) * SDI / sm, log(byi), pl)
sim <- function(dbh, ht, ex, byi, pl, years, sm, bg, bm) { out <- matrix(NA_real_, years + 1, 4, dimnames = list(NULL, c("BA", "TPH", "QMD", "SDI"))); for (y in 0:years) { s <- koa_stand(dbh, ht, ex); out[y + 1, ] <- c(s$BA, s$TPH, s$QMD, s$SDI); if (y == years) break
    bal <- koa_bal(dbh, s$ba); rd <- s$SDI / sm; g <- as.numeric(exp(xm(dbh, bal, s$BA, s$SDI, sm, byi, pl) %*% bg)); pm <- 1 - exp(-exp(as.numeric(cbind(1, log(dbh + 1), dbh, dbh^2, bal, log(max(rd, 0.001)), log(byi), pl) %*% bm))); ht <- ht + koa_height(dbh + g, cf) - koa_height(dbh, cf); dbh <- dbh + g; ex <- ex * (1 - pm) }; out }
startv <- tr[Status == "live" & !is.na(DBH) & DBH > 0, .(n = .N), by = .(pid, Measure)][n >= 5][, .SD[which.min(Measure)], by = pid]
PI <- Filter(Negate(is.null), lapply(seq_len(nrow(startv)), function(i) { p <- startv$pid[i]; m0 <- startv$Measure[i]; L <- tr[pid == p & Measure == m0 & Status == "live" & !is.na(DBH) & DBH > 0]; L[is.na(HT) | HT < 1.37, HT := koa_height(DBH, cf)]; later <- sort(unique(tr[pid == p & Measure > m0, Measure])); if (nrow(f$srep[pid == p & Measure >= m0])) later <- later[later <= min(f$srep[pid == p & Measure >= m0, Measure])]
  ry <- REM[Data == L$Data[1] & Install == as.character(L$Install[1]) & yr > m0, yr]; if (length(ry)) later <- later[later < min(ry)]; if (!length(later)) return(NULL)
  obs <- rbindlist(lapply(later, function(m1) { ob <- merge(tr[pid == p & Measure == m1 & uid %in% L$uid & Status == "live", .(uid, DBH_c)], L[, .(uid, EXPF_c)], by = "uid"); if (!nrow(ob)) return(NULL); data.table(h = m1 - m0, o_surv = sum(ob$EXPF_c) / sum(L$EXPF_c), o_qmd = sqrt(sum(ob$DBH_c^2 * ob$EXPF_c) / sum(ob$EXPF_c)), o_ba = sum(0.00007854 * ob$DBH_c^2 * ob$EXPF_c)) })); if (!nrow(obs)) return(NULL); list(p = p, L = L, pl = L$planted[1], byi = L$BYI[1], obs = obs, N0 = sum(L$EXPF_c)) }))
bench <- function(n) rbindlist(lapply(PI, function(x) { z <- sim(x$L$DBH, x$L$HT, x$L$EXPF_c, x$byi, x$pl, max(x$obs$h), SMapp[[n]][[x$p]], BG[[n]], BM[[n]]$b); cbind(pid = x$p, planted = x$pl, x$obs, p_surv = z[x$obs$h + 1, "TPH"] / x$N0, p_qmd = z[x$obs$h + 1, "QMD"], p_ba = z[x$obs$h + 1, "BA"]) }))
BB <- lapply(setNames(names(SMfit), names(SMfit)), bench); rm1 <- function(b, v) sqrt(mean((b[[paste0("o_", v)]] - b[[paste0("p_", v)]])^2)); bi <- function(b, v) mean(b[[paste0("o_", v)]] - b[[paste0("p_", v)]])
cat("\nbenchmark with removals censored: plots", uniqueN(BB$own$pid), " plot-horizons", nrow(BB$own), " planted plots", uniqueN(BB$own[planted == 1, pid]), " natural", uniqueN(BB$own[planted == 0, pid]), "; longest horizon by origin (natural, planted):", BB$own[, max(h), by = planted][order(planted), V1], "; plots with a horizon of 10 years or more:", uniqueN(BB$own[h >= 10, pid]), "\n")
print(rbindlist(lapply(names(BB), function(n) data.table(SDImax = n, surv_bias = round(bi(BB[[n]], "surv"), 3), surv_rmse = round(rm1(BB[[n]], "surv"), 3), qmd_bias = round(bi(BB[[n]], "qmd"), 2), qmd_rmse = round(rm1(BB[[n]], "qmd"), 2), ba_bias = round(bi(BB[[n]], "ba"), 2), ba_rmse = round(rm1(BB[[n]], "ba"), 2), ba_rmse_planted = round(rm1(BB[[n]][planted == 1], "ba"), 2), ba_rmse_natural = round(rm1(BB[[n]][planted == 0], "ba"), 2), ba_rmse_h10 = round(rm1(BB[[n]][h >= 10], "ba"), 2)))))
pl <- split(seq_len(nrow(BB$own)), BB$own$pid); pn <- names(pl); pd <- function(x, y, v) { d <- replicate(2000, { ix <- unlist(pl[sample(pn, length(pn), TRUE)], use.names = FALSE); rm1(BB[[x]][ix], v) - rm1(BB[[y]][ix], v) }); round(c(diff = rm1(BB[[x]], v) - rm1(BB[[y]], v), quantile(d, c(.025, .975))), 3) }
cat("paired plot-cluster bootstrap (2,000) of the difference in RMSE with 95% interval:\n"); for (cmp in list(c("byi_origin", "one742"), c("byi_origin", "origin"), c("own", "byi_origin"))) for (v in c("ba", "surv", "qmd")) cat(sprintf("  %s minus %s, %-4s: %s\n", cmp[1], cmp[2], v, paste(pd(cmp[1], cmp[2], v), collapse = " ")))
l <- BB$one742[, .SD[which.max(h)], by = pid]; l <- merge(l, P[, .(pid, lbyi)], by = "pid"); m <- lm(log(o_ba / p_ba) ~ lbyi + planted, l); cat("residuals of the one-value system at each plot's longest horizon, ln(observed/projected basal area) on ln(BYI) and origin:", paste(names(coef(m)), sprintf("%.3f (%.3f)", coef(m), sqrt(diag(vcov(m)))), collapse = "; "), sprintf(" R2 %.3f, plots %d\n", summary(m)$r.squared, nrow(l)))
vis <- tr[Status == "live" & !is.na(DBH) & DBH > 0, .(n = .N, q = sqrt(sum(DBH^2 * EXPF_c) / sum(EXPF_c))), by = .(pid, Measure, planted)][n >= 10]; byiq <- unique(tr[, .(pid, planted, BYI)])[, .(lo = quantile(BYI, .1), md = quantile(BYI, .5), hi = quantile(BYI, .9)), by = planted]; pick <- vis[, .SD[which.min(abs(q - quantile(q, 0.25)))], by = planted]
getL <- function(p) { pv <- pick[planted == p]; L <- tr[pid == pv$pid & Measure == pv$Measure & Status == "live" & !is.na(DBH) & DBH > 0]; L[is.na(HT) | HT < 1.37, HT := koa_height(DBH, cf)]; L }; LIM <- c(`0` = 1.2 * 1410.063, `1` = 1.2 * 1135.136)
smf <- list(one742 = function(p, by) POP, origin = function(p, by) exp(predict(s2(ls ~ planted, M), data.table(planted = p))), byi_origin = function(p, by) exp(predict(s2(ls ~ lbyi + planted, M), data.table(lbyi = log(by), planted = p))))
cat("\n200-year gates by treatment (starting plot's own value not run: it is not available for a new stand)\n"); print(rbindlist(lapply(names(smf), function(n) { S <- rbindlist(lapply(c(0, 1), function(p) { L <- getL(p); rbindlist(lapply(c("lo", "md", "hi"), function(lv) { by <- byiq[planted == p][[lv]]; cbind(planted = p, level = lv, year = 0:200, as.data.table(sim(L$DBH, L$HT, L$EXPF_c, by, p, 200, smf[[n]](p, by), BG[[n]], BM[[n]]$b))) })) }))
  L1 <- getL(1); bmd <- byiq[planted == 1, md]; DS <- rbindlist(lapply(c(300, 600, 1200, 2400), function(n0) cbind(n0 = n0, year = 0:100, as.data.table(sim(L1$DBH, L1$HT, L1$EXPF_c * n0 / sum(L1$EXPF_c), bmd, 1, 100, smf[[n]](1, bmd), BG[[n]], BM[[n]]$b))))); w <- dcast(S, planted + year ~ level, value.var = c("BA", "QMD", "TPH")); fo <- function(p) { o <- w[planted == p & year >= 1 & !(BA_lo <= BA_md + 1e-9 & BA_md <= BA_hi + 1e-9), year]; if (length(o)) min(o) else NA_integer_ }
  data.table(SDImax = n, site_to_100 = w[year >= 1 & year <= 100, all(BA_lo <= BA_md + 1e-9 & BA_md <= BA_hi + 1e-9 & QMD_lo <= QMD_md + 1e-9 & QMD_md <= QMD_hi + 1e-9)], sdi_lim = S[, max(SDI) <= LIM[as.character(planted[1])], by = planted][, all(V1)], ba200 = S[year == 200, all(BA <= 89.6)], no_rise = S[, SDI[year == 200] / SDI[year == 150] <= 1.05, by = .(planted, level)][, all(V1)],
    sukachev = w[year %in% c(40, 100), all(TPH_md <= TPH_lo * 1.02 & TPH_hi <= TPH_md * 1.02)], yield_dens = DS[year %in% c(20, 40, 100), all(diff(BA[order(n0)]) >= -1e-9), by = year][, all(V1)], ba_out_nat = fo(0), ba_out_plt = fo(1), ba100_nat = paste(round(w[planted == 0 & year == 100, c(BA_lo, BA_md, BA_hi)], 1), collapse = "/"), ba100_plt = paste(round(w[planted == 1 & year == 100, c(BA_lo, BA_md, BA_hi)], 1), collapse = "/"), ba200_max = round(S[year == 200, max(BA)], 1)) })))
cat("\n25 done\n")
